ALTER TABLE public.trip_network_settings ADD COLUMN pilot_config jsonb NOT NULL DEFAULT '{"enabled":false,"emergencyStop":false,"senders":[],"receivers":[],"services":[],"cities":[],"zips":[],"maxCandidates":5,"responseMinutes":60,"maxRadius":20,"inApp":false}'::jsonb;
ALTER TABLE public.trip_distributions ADD COLUMN pilot_wave boolean NOT NULL DEFAULT false, ADD COLUMN pickup_timezone text;
ALTER TABLE public.account_security_audit ADD COLUMN details jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE FUNCTION public.matching_pilot_config() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Master Admin required'; END IF; RETURN coalesce((SELECT pilot_config FROM public.trip_network_settings WHERE id=true),'{"enabled":false,"emergencyStop":false,"senders":[],"receivers":[],"services":[],"cities":[],"zips":[],"maxCandidates":5,"responseMinutes":60,"maxRadius":20,"inApp":false}'::jsonb); END $$;
CREATE FUNCTION public.save_matching_pilot(_config jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prev jsonb;d record;o record; BEGIN IF NOT public.has_role(auth.uid(),'admin') OR length(trim(_reason)) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'Master Admin and change reason required';END IF;SELECT pilot_config INTO prev FROM public.trip_network_settings WHERE id=true FOR UPDATE;IF prev IS NULL THEN RAISE EXCEPTION 'Existing distribution settings required';END IF;
IF jsonb_typeof(_config->'enabled') IS DISTINCT FROM 'boolean' OR jsonb_typeof(_config->'emergencyStop') IS DISTINCT FROM 'boolean' OR jsonb_typeof(_config->'inApp') IS DISTINCT FROM 'boolean' OR jsonb_typeof(_config->'senders') IS DISTINCT FROM 'array' OR jsonb_typeof(_config->'receivers') IS DISTINCT FROM 'array' OR jsonb_typeof(_config->'services') IS DISTINCT FROM 'array' OR jsonb_typeof(_config->'cities') IS DISTINCT FROM 'array' OR jsonb_typeof(_config->'zips') IS DISTINCT FROM 'array' OR coalesce((_config->>'maxCandidates')::int,0) NOT BETWEEN 1 AND 25 OR coalesce((_config->>'responseMinutes')::int,0) NOT BETWEEN 5 AND 1440 OR coalesce((_config->>'maxRadius')::int,0) NOT IN (20,50,100,200) OR _config ?| ARRAY['email','sms','automatic','global'] THEN RAISE EXCEPTION 'Invalid bounded pilot configuration';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(_config->'senders') x WHERE NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=x::uuid AND account_type='provider' AND status='active' AND NOT is_test_account)) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(_config->'receivers') x WHERE NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=x::uuid AND account_type='provider' AND status='active' AND NOT is_test_account)) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(_config->'services') x WHERE x NOT IN ('ambulatory','wheelchair','stretcher')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(_config->'zips') x WHERE x !~ '^[0-9]{5}$') THEN RAISE EXCEPTION 'Invalid pilot scope';END IF;
IF (_config->>'enabled')::boolean AND (jsonb_array_length(_config->'senders')=0 OR jsonb_array_length(_config->'receivers')=0 OR jsonb_array_length(_config->'services')=0 OR jsonb_array_length(_config->'cities')+jsonb_array_length(_config->'zips')=0) THEN RAISE EXCEPTION 'Explicit workspace, service and geography scope required';END IF;
IF EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key IN ('nearby_matching','nearby_auto_waves') AND enabled) THEN RAISE EXCEPTION 'Global matching and automatic waves must remain off';END IF;
UPDATE public.trip_network_settings SET pilot_config=_config,updated_by=auth.uid(),updated_at=now() WHERE id=true;
INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'matching_pilot_changed','recorded',jsonb_build_object('previous',prev,'new',_config,'reason',trim(_reason)));
IF coalesce((_config->>'emergencyStop')::boolean,false) AND NOT coalesce((prev->>'emergencyStop')::boolean,false) THEN FOR d IN SELECT id FROM public.trip_distributions WHERE pilot_wave AND selected_workspace_id IS NULL LOOP PERFORM public.network_audit(d.id,NULL,'pilot_emergency_stop',jsonb_build_object('reason',trim(_reason)));FOR o IN SELECT id,provider_workspace_id FROM public.provider_trip_offers WHERE distribution_id=d.id AND status IN ('pending','countered','revised') LOOP PERFORM public.network_notify(o.provider_workspace_id,'Pilot emergency stop',o.id,true);END LOOP;END LOOP;END IF;END $$;
CREATE FUNCTION public.pilot_scope_reason(_distribution uuid,_receiver uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;d public.trip_distributions;z text;BEGIN SELECT pilot_config INTO c FROM public.trip_network_settings WHERE id=true;SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution;
IF NOT coalesce((c->>'enabled')::boolean,false) OR NOT coalesce((c->>'inApp')::boolean,false) OR coalesce((c->>'emergencyStop')::boolean,true) THEN RETURN 'Pilot disabled or stopped';END IF;
IF NOT coalesce(c->'senders' @> to_jsonb(ARRAY[d.source_workspace_id::text]),false) OR NOT coalesce(c->'services' @> to_jsonb(ARRAY[d.capability]),false) OR (_receiver IS NOT NULL AND (NOT coalesce(c->'receivers' @> to_jsonb(ARRAY[_receiver::text]),false) OR _receiver=d.source_workspace_id)) THEN RETURN 'Outside pilot scope';END IF;
IF d.pickup_timezone IS NULL OR d.pickup_timezone NOT IN ('America/New_York','America/Chicago') OR (d.pickup_date+d.pickup_time) AT TIME ZONE d.pickup_timezone<=now() THEN RETURN 'Pickup timezone or future time required';END IF;
SELECT pickup_zip INTO z FROM public.trips WHERE id=d.trip_id;IF z IS NULL THEN SELECT pickup_zip INTO z FROM public.ride_requests WHERE id=d.request_id;END IF;
IF NOT coalesce(c->'cities' @> to_jsonb(ARRAY[d.pickup_area]),false) AND NOT coalesce(c->'zips' @> to_jsonb(ARRAY[z]),false) THEN RETURN 'Authoritative pilot geography required';END IF;RETURN '';END $$;
REVOKE ALL ON FUNCTION public.pilot_scope_reason(uuid,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.matching_pilot_config(),public.save_matching_pilot(jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.matching_pilot_config(),public.save_matching_pilot(jsonb,text) TO authenticated;